 @TempDir Path temporary;
 private static String requiredProperty(String name){String value=System.getProperty(name);if(value==null||value.isBlank())throw new IllegalStateException("NOT_RUN_REQUIRED_INPUT: "+name);return value;}
 private record Input(ObjectNode raw,ExactRef producer,ExactRef source,ExactRef runReceipt){ }
 private static Input actualDenied()throws IOException{
  String configured=System.getProperty("xar.religion.holy.ui.denied.manifest");if(configured==null||configured.isBlank())throw new IllegalStateException("NOT_RUN_REQUIRED_ACTUAL_HOLY_UI_DENIED_MANIFEST: existing ingame_ui_navigation_v1_test must produce holy-site-denied.json");
  Path path=Path.of(configured);assertTrue(path.isAbsolute());var manifest=SharedSourceFiles.observe(path);assertEquals(Long.parseLong(requiredProperty("xar.fullParity.fixture.RELIGION_HOLY_UI_DENIED_NATIVE_SET.bytes")),manifest.source().bytes());assertEquals(requiredProperty("xar.religion.holy.ui.denied.manifest.sha256"),manifest.source().sha256());SharedSourceFiles.assertUnchanged(manifest);ObjectNode n=StrictJson.object(StrictJson.parse(Files.readAllBytes(path)),Set.of("schema","machine_id","observed_at_utc","producer","producer_source","run_receipt","packet"));assertEquals("xar.holy-ui-original-serializer-fixture/v1",StrictJson.text(n.get("schema")));String machine=StrictJson.text(n.get("machine_id"));assertFalse(machine.equals("unknown"));java.time.Instant.parse(StrictJson.text(n.get("observed_at_utc")));ExactRef producer=pin(n.get("producer")),source=pin(n.get("producer_source")),receipt=pin(n.get("run_receipt")),packet=pin(n.get("packet"));assertEquals(Path.of(requiredProperty("xar.repository.root")).resolve("ck3_autonomous_player/native_bridge/tests/ingame_ui_navigation_v1_test.cpp").toAbsolutePath().normalize(),Path.of(source.path()).toAbsolutePath().normalize());assertTrue(producer.path().toLowerCase(java.util.Locale.ROOT).endsWith(".exe"));assertEquals("holy-site-denied.json",Path.of(packet.path()).getFileName().toString());ObjectNode run=ReligionCodec.object(new RawJson(Files.readAllBytes(Path.of(receipt.path()))));assertEquals(0,StrictJson.integer(run.get("exit_code"),0,0));assertEquals(producer,ExactRef.fromJson(run.get("executable")));assertEquals(source,ExactRef.fromJson(run.get("producer_source")));assertEquals(packet,ExactRef.fromJson(run.get("packet")));assertEquals(machine,StrictJson.text(run.get("machine_id")));java.time.Instant.parse(StrictJson.text(run.get("observed_at_utc")));ObjectNode raw=ReligionCodec.object(new RawJson(Files.readAllBytes(Path.of(packet.path()))));return new Input(raw,producer,source,receipt);
 }
 private static ExactRef pin(JsonNode node)throws IOException{ExactRef expected=ExactRef.fromJson(node);var observed=SharedSourceFiles.observe(Path.of(expected.path()));assertEquals(expected.bytes(),observed.source().bytes());assertEquals(expected.sha256(),observed.source().sha256());SharedSourceFiles.assertUnchanged(observed);return expected;}
 private static Frame frame(ObjectNode n){return new Frame(n.get("native_revision").bigIntegerValue(),n.get("date_raw").bigIntegerValue(),n.get("played_character_id").bigIntegerValue(),BigInteger.valueOf(5));}
 private static Selection open(ObjectNode n){return new Selection(Operation.OPEN_SITE,n.get("requested_subject_id").bigIntegerValue(),Optional.empty(),Optional.empty(),Optional.empty());}
 @Test void originalParsedReturnArchiveUsesTheOneTypedProducerAndPreservesUnvalidatedData()throws Exception{
  ObjectNode raw=actualDenied().raw();String requestId="holy-original-parsed-return-data";ObjectNode fields=ReligionHolyUi.nativeFields(open(raw),frame(raw));byte[] request=NativeWire.execute(requestId,"navigate-ingame-ui-v1",frame(raw).nativeRevision(),StrictJson.canonical(fields));ObjectNode returned=StrictJson.object().put("type","command_result").put("protocol_version",1).put("request_id",requestId).put("ok",false);returned.set("result",raw);byte[] response=NativeWire.packet(StrictJson.canonical(returned));ObjectNode before=StrictJson.object().put("software_fixture_only",true);before.set("native_revision",raw.get("native_revision"));before.set("date_raw",raw.get("date_raw"));before.putObject("played_character").set("character_id",raw.get("played_character_id"));var snapshot=OpportunityJson.object(OpportunityJson.parse(StrictJson.canonical(before)),"software parsed-return snapshot DATA");RawJson encoded=NativeUiParsedReturn.encode(request,response,snapshot);ObjectNode artifact=(ObjectNode)OpportunityJson.toNode(NativeUiParsedReturn.decode(encoded.bytes()));assertEquals(NativeUiParsedReturn.SCHEMA,StrictJson.text(artifact.get("schema")));assertEquals("unvalidated",StrictJson.text(artifact.get("validation_state")));assertTrue(artifact.get("wire_bytes_preserved").isBoolean());assertFalse(artifact.get("wire_bytes_preserved").booleanValue());assertEquals(returned,artifact.get("original_parsed_command_result"));assertEquals(before,artifact.get("actual_pre_submission_snapshot"));assertEquals(StrictJson.parse(java.util.Arrays.copyOfRange(request,4,request.length)),artifact.get("request"));Path saved=temporary.resolve("original-parsed-return.json");Files.write(saved,encoded.bytes());var pin=SharedSourceFiles.observe(saved);ExactRef artifactSource=new ExactRef(pin.source().path(),pin.source().bytes(),pin.source().sha256());ObjectNode reference=NativeUiParsedReturn.reference(artifactSource);StrictJson.object(reference,Set.of("path","bytes","sha256","validation_state"));assertEquals(artifactSource,ExactRef.fromJson(StrictJson.object().put("path",StrictJson.text(reference.get("path"))).put("bytes",StrictJson.integer(reference.get("bytes"),0,NativeUiParsedReturn.MAXIMUM_ARTIFACT_BYTES)).put("sha256",StrictJson.text(reference.get("sha256")))));assertEquals("unvalidated",StrictJson.text(reference.get("validation_state")));assertThrows(IllegalArgumentException.class,()->NativeUiParsedReturn.encode(request,NativeWire.packet(StrictJson.canonical(returned.deepCopy().put("request_id","other"))),snapshot));
 }
 @Test void actualOriginalCppFailClosedPacketCrossesTheJavaNormalizerAndPreservesEveryField()throws Exception{Input actual=actualDenied();ObjectNode before=actual.raw().deepCopy();Observation observed=ReligionHolyUi.decode(ReligionCodec.raw(before),open(before),frame(before));assertFalse(observed.available());assertFalse(observed.attempted());assertFalse(observed.dispatched());assertFalse(observed.pending());assertTrue(observed.knownNoDispatch());assertEquals(before,ReligionCodec.object(observed.original()));assertEquals(before,actual.raw());assertEquals(observed.original(),ReligionCodec.raw(ReligionCodec.object(observed.original())));}
 @Test void nativeTypesBuildOwnerAndSourceParametersNeverAcquireDefaultValues()throws Exception{ObjectNode raw=actualDenied().raw();Selection selection=open(raw);Frame frame=frame(raw);for(String field:List.of("requested_subject_id","native_revision","date_raw","played_character_id","thread_id","pump_epoch","gui_context_address","gui_owner_address"))for(JsonNode bad:List.of(StrictJson.object().put("x",true).get("x"),StrictJson.object().put("x",1.0).get("x"),StrictJson.object().put("x","1").get("x"),com.fasterxml.jackson.databind.node.NullNode.instance)){ObjectNode invalid=raw.deepCopy();invalid.set(field,bad);assertThrows(RuntimeException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(invalid),selection,frame),field);}
  for(String field:List.of("accepted","available","dispatch_invoked","verification_pending","owner_character_id_available","native_dispatch_attempted")){ObjectNode invalid=raw.deepCopy().put(field,0);assertThrows(RuntimeException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(invalid),selection,frame));ObjectNode missing=raw.deepCopy();missing.remove(field);assertThrows(RuntimeException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(missing),selection,frame));}assertThrows(IllegalArgumentException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(raw.deepCopy().put("executable_sha256","a".repeat(64))),selection,frame));assertThrows(IllegalArgumentException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(raw.deepCopy().put("game_version","1.20.0.3")),selection,frame));
 }
 @Test void syntheticCallbackAckRemainsUnknownAndCannotInventAWorldOrSelectionPostcondition()throws Exception{ObjectNode n=actualDenied().raw().deepCopy();Frame frame=frame(n);Selection create=new Selection(Operation.CREATE,BigInteger.ZERO,Optional.empty(),Optional.empty(),Optional.of("a".repeat(64)));n.put("window_kind","holy_site_creation").put("window_name","holy_site_creation_window").put("requested_subject_id",0).put("status","verification_pending").put("unavailable_reason","synthetic contract ACK only, not native/Game evidence").put("accepted",false).put("available",false).put("native_dispatch_attempted",true).put("dispatch_invoked",true).put("verification_pending",true).put("application_owner_thread_verified",true).put("gui_owner_binding_verified",true).put("thread_id",1).put("pump_epoch",1).put("gui_context_address",1).put("gui_owner_address",1);((ObjectNode)n.get("tree")).put("scope_root_name","holy_site_creation_window");n.putObject("modal_admission").put("attempted",true).put("header_read",true).put("receivers_verified",true).put("effective_visible_count",0).put("effective_hidden_mask",8).put("policy","refuse_any_effective_visible_receiver");var ui=n.putObject("holy_site_creation_ui").put("operation","create_holy_site_once").putNull("type_key").putNull("selected").put("requested_object_id",0).put("postcondition_observed",false).put("selection_verified",false).put("create_dispatched",true).putNull("context").put("business_outcome_observed",false).put("expected_preview_identity_sha256","a".repeat(64));Observation observed=ReligionHolyUi.decode(ReligionCodec.raw(n),create,frame);assertTrue(observed.pending());assertFalse(observed.available());assertFalse(observed.knownNoDispatch());assertTrue(observed.attempted());for(String credit:List.of("postcondition_observed","selection_verified","business_outcome_observed")){ObjectNode invalid=n.deepCopy();((ObjectNode)invalid.get("holy_site_creation_ui")).put(credit,true);assertThrows(IllegalArgumentException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(invalid),create,frame));}ObjectNode falseNoAttempt=n.deepCopy().put("native_dispatch_attempted",false);assertThrows(IllegalArgumentException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(falseNoAttempt),create,frame));ObjectNode noOwner=n.deepCopy().put("gui_owner_address",0);assertThrows(IllegalArgumentException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(noOwner),create,frame));ObjectNode modal=n.deepCopy();((ObjectNode)modal.get("modal_admission")).put("effective_visible_count",1);assertThrows(IllegalArgumentException.class,()->ReligionHolyUi.decode(ReligionCodec.raw(modal),create,frame));
 }
 @Test void actualOriginalPythonNormalizerAgreesOnCompleteCppDeniedBodyInAnIndependentProcess()throws Exception{ObjectNode raw=actualDenied().raw();String repository=System.getProperty("xar.repository.root");if(repository==null||repository.isBlank())throw new IllegalStateException("NOT_RUN_REQUIRED_ORIGINAL_RELIGION_REPOSITORY");Path repo=Path.of(repository);Path original=repo.resolve("ck3_autonomous_player/src/xar_autoplayer/bridge/ingame_ui_contract.py");var source=SharedSourceFiles.observe(original);SharedSourceFiles.assertUnchanged(source);String program="""
import json,pathlib,sys
sys.path.insert(0,str(pathlib.Path(sys.argv[1])/'ck3_autonomous_player'/'src'))
from xar_autoplayer.bridge.ingame_ui_contract import normalize_ui_result
from xar_autoplayer.bridge.version_identity import CK3_12004
n=json.load(sys.stdin)
r=normalize_ui_result(n,operation='open_holy_site',kind='holy_site',subject_id=n['requested_subject_id'],native_revision=n['native_revision'],date_raw=n['date_raw'],actor_id=n['played_character_id'],expected_build=CK3_12004)
json.dump(r,sys.stdout,ensure_ascii=False,separators=(',',':'))
""";Path output=temporary.resolve("original-ui.stdout"),error=temporary.resolve("original-ui.stderr");var builder=new ProcessBuilder(requiredProperty("xar.python"),"-I","-B","-c",program,repo.toString());builder.environment().put("PYTHONDONTWRITEBYTECODE","1");builder.redirectOutput(output.toFile()).redirectError(error.toFile());var process=builder.start();try(var input=process.getOutputStream()){input.write(StrictJson.canonical(raw));}assertTrue(process.waitFor(30,TimeUnit.SECONDS),"original Python Holy UI oracle timeout");assertEquals(0,process.exitValue(),Files.readString(error));assertEquals(ReligionCodec.object(ReligionHolyUi.decode(ReligionCodec.raw(raw),open(raw),frame(raw)).original()),StrictJson.parse(Files.readAllBytes(output)));SharedSourceFiles.assertUnchanged(source);}
